function updateLikeState(result){if(typeof result.source_version==='number'&&typeof state.likeVersion==='number'&&result.source_version<state.likeVersion)return;if(typeof result.source_version==='number')state.likeVersion=result.source_version;state.likes=result.likes||state.likes;var count=typeof result.count==='number'?result.count:state.likes.length;state.me.readiness={likes_count:count,explained_count:result.explained_count||0,target:10,ready:count>=10}}
