function renderAccount(){var m=state.me,active=m.subscription&&m.subscription.active,manageable=!!(m.subscription&&m.subscription.manageable),subStatus=m.subscription&&m.subscription.status,billing=m.configuration&&m.configuration.billing,canSubscribe=!active&&(!subStatus||['none','canceled','incomplete_expired'].includes(subStatus));var canStart=readiness().likes_count>=10&&consented()&&m.configuration&&m.configuration.ai;var view=document.getElementById('view');view.innerHTML='<section class="panel narrow"><h2>Votre espace, vos choix.</h2><div class="account-row"><h3>Mon compte</h3><p id="account-email" class="muted"></p></div><div class="account-row"><div class="row"><div><h3>Une histoire personnelle chaque jour</h3><p class="muted" id="subscription-copy"></p></div><div class="price">10 € <small>/ mois</small></div></div><div id="account-progress"></div><div id="billing-action"></div><p id="billing-status" class="status" role="status"></p></div><div class="account-row"><h3>Mon accord pour la personnalisation</h3><div id="account-consent"></div><p class="helper">Retirer votre accord suspend les analyses et les nouvelles histoires. Cela ne résilie pas l’abonnement ; utilisez l’espace de facturation pour le résilier.</p></div><div class="account-row"><h3>Conserver une copie</h3><p class="muted">Exportez vos articles aimés, vos retours et vos histoires.</p><button type="button" class="secondary" id="export-button">Exporter mon journal</button><p id="export-status" class="status" role="status"></p></div><div class="account-row"><details class="privacy-details"><summary>Comment mes choix sont-ils utilisés ?</summary><p class="legal-space">Vos lectures aimées, leurs thèmes et vos explications permettent de proposer un portrait. Celui-ci reste une interprétation, pas un diagnostic ni une mesure définitive de votre personnalité.</p><p>Avec votre accord, ces informations, vos retours et vos corrections sont transmis à OpenRouter. Le personnage est fictif et les histoires explorent des situations possibles : elles ne décrivent pas des événements qui vous sont réellement arrivés.</p><p>Vous pouvez retirer un J’aime, effacer une explication ou corriger une interprétation. Les analyses suivantes tiennent compte de ces changements.</p></details></div><div class="account-row"><h3>Supprimer mon compte</h3><p class="muted">Votre journal et vos données seront supprimés, et votre abonnement résilié.</p><button type="button" class="text danger" id="delete-button">Supprimer mon compte et mes données</button></div></section>';document.getElementById('account-email').textContent=m.user.email;document.getElementById('subscription-copy').textContent=active?'Votre abonnement est actif. Gérez vos factures et la résiliation dans votre espace de facturation.':['past_due','unpaid','incomplete'].includes(subStatus)?'Votre paiement nécessite une vérification. Retrouvez vos factures et votre moyen de paiement dans l’espace de facturation.':'À partir de 10 articles aimés et de votre accord, recevez des histoires qui évoluent avec vos retours.';document.getElementById('account-progress').append(progressBlock());document.getElementById('account-consent').append(consentForm());var area=document.getElementById('billing-action');function billingButton(label,path,cls){return actionButton(label,async function(e){var b=e.currentTarget;b.disabled=true;status('billing-status','Ouverture de votre espace de paiement…');try{var data=await api(path,'POST',{});var u=new URL(data.url);if(u.protocol!=='https:')throw new Error('Le lien de paiement est indisponible.');location.assign(u.href)}catch(err){status('billing-status',err.message,true);b.disabled=false}},cls)}if(!billing)area.append(el('div','notice warn','Les nouveaux abonnements ne sont pas encore ouverts. Vous pouvez déjà aimer des articles et préparer votre journal.'));var actions=el('div','actions');if(canSubscribe&&billing){var subscribe=billingButton(manageable?'Reprendre mon abonnement à 10 € par mois':'M’abonner pour 10 € par mois','/api/billing/checkout');subscribe.disabled=!canStart;actions.append(subscribe);if(!canStart)area.append(el('p','helper',readiness().likes_count<10?'Aimez au moins 10 articles pour accéder à l’abonnement.':!consented()?'Donnez votre accord ci-dessous pour la personnalisation avant de vous abonner.':'La personnalisation attend l’activation de l’IA avant l’ouverture de votre abonnement.'))}if(manageable)actions.append(billingButton(canSubscribe?'Mes factures et moyens de paiement':'Gérer mon abonnement','/api/billing/portal',canSubscribe?'secondary':''));area.append(actions);document.getElementById('export-button').addEventListener('click',async function(e){var b=e.currentTarget;b.disabled=true;status('export-status','Préparation…');try{var data=await api('/api/export');var url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));var a=el('a');a.href=url;a.download='mon-journal-decode-ton-esprit.json';document.body.append(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1000);status('export-status','Votre téléchargement est lancé.')}catch(err){status('export-status',err.message,true)}finally{b.disabled=false}});document.getElementById('delete-button').addEventListener('click',function(){document.getElementById('delete-form').reset();status('delete-status','');document.getElementById('delete-dialog').showModal()})}
async function logout(){try{await api('/api/auth/logout','POST',{});state.me=null;state.likes=[];state.likeVersion=null;state.stories=[];state.drafts.clear();state.selected=null;landing()}catch(err){alert(err.message)}}
document.addEventListener('click',function(e){var auth=e.target.closest('[data-auth]');if(auth)openAuth(auth.dataset.auth);var close=e.target.closest('[data-close]');if(close)document.getElementById(close.dataset.close).close()});
document.getElementById('auth-form').addEventListener('submit',async function(e){e.preventDefault();var form=e.currentTarget;busy(form,true);status('auth-status','Connexion…');try{await api('/api/auth/'+state.authMode,'POST',formValues(form));state.tab=state.authMode==='register'||state.pendingArticle?'likes':'journal';await refresh();document.getElementById('auth-dialog').close();form.reset()}catch(err){status('auth-status',err.message,true)}finally{busy(form,false)}});
